INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('bewegung-oesterreich-50-tage-bewegung-2026-bilanz-fgoe','Bewegung in Österreich: Nur knapp ein Viertel schafft die Empfehlung','Mehr als 1.700 Gratis-Angebote bei „50 Tage Bewegung“ – doch laut Statistik Austria erfüllen nur 23,6 Prozent der Erwachsenen die Bewegungsempfehlungen.','Bewegung in Österreich bleibt ein Sorgenkind der Gesundheitsvorsorge: Nur 23,6 Prozent der 18- bis 64-Jährigen kommen sowohl beim Ausdauertraining als auch bei der Muskelkräftigung auf das empfohlene Maß. Das hält der Fonds Gesundes Österreich (FGÖ) in seiner Bilanz zur Initiative „50 Tage Bewegung“ fest, die am Nationalfeiertag zu Ende gegangen ist. Die Zahlen stammen von Statistik Austria.

## 50 Tage Bewegung 2026: Die Bilanz

Vom 7. September bis zum 26. Oktober 2026 haben Gemeinden, Sportvereine und Organisationen in allen Bundesländern zum Mitmachen eingeladen. Insgesamt standen laut FGÖ **mehr als 1.700 kostenlose Bewegungsangebote** zur Verfügung, die sich an alle Altersgruppen richteten.

Das Spektrum war breit gefächert und bewusst niederschwellig gehalten. Angeboten wurden unter anderem:

- Gehen, Wandern und Radfahren
- Laufen und Tanzen
- Yoga und Tai-Chi
- Sesselgymnastik, etwa für ältere Menschen
- Schnupperstunden in Sportarten wie LaCrosse

Ziel der Aktion ist es, Bewegung dauerhaft in den Alltag einzubauen und vor allem jenen Menschen den Einstieg zu erleichtern, die bisher wenig aktiv sind. Den Abschluss bildete eine Veranstaltung am 26. Oktober in Wien, bei der Gäste aus Sport, Politik und Unterhaltung auftraten. ORF 2 berichtete mit Liveschaltungen aus allen Bundesländern.

## Bewegung in Österreich: Wie aktiv sind die Menschen?

Die Daten zeigen, dass zwischen Empfehlung und Alltag eine große Lücke klafft. Weniger als die Hälfte der Erwachsenen im erwerbsfähigen Alter erreicht die Mindestmenge von 150 Minuten Bewegung pro Woche. Noch deutlich kleiner ist der Anteil jener, die zusätzlich auch regelmäßig ihre Muskulatur trainieren – hier liegt der Wert bei 23,6 Prozent.

FGÖ-Leiter Klaus Ropin verweist in der Aussendung einerseits auf das große Interesse an den kostenlosen Angeboten, andererseits darauf, dass sich nach wie vor zu wenige Menschen ausreichend bewegen. Gesundheitsministerin Korinna Schumann und Sport-Staatssekretärin Michaela Schmidt betonten den Wert gemeinsamer Aktivität für die körperliche und psychische Gesundheit.

## Österreichische Bewegungsempfehlungen im Überblick

Die Österreichischen Bewegungsempfehlungen, auf die sich der FGÖ bezieht, orientieren sich an den Vorgaben der Weltgesundheitsorganisation (WHO). Für den Alltag lassen sie sich auf zwei Richtwerte herunterbrechen:

1. **Erwachsene:** mindestens 150 Minuten pro Woche bei mittlerer Intensität – etwa zügiges Gehen oder gemütliches Radfahren. Dazu kommen Übungen zur Kräftigung der Muskulatur.
2. **Kinder und Jugendliche von 6 bis 18 Jahren:** mindestens 60 Minuten Bewegung pro Tag.

Auf die Woche verteilt entsprechen 150 Minuten etwa einer halben Stunde an fünf Tagen. Wer den Arbeitsweg teilweise zu Fuß oder mit dem Rad zurücklegt, Stiegen statt Lift nimmt oder abends eine Runde spazieren geht, kommt diesem Wert bereits deutlich näher.

## Wer hinter der Initiative steht

„50 Tage Bewegung“ ist eine gemeinsame Aktion des FGÖ, eines Geschäftsbereichs der Gesundheit Österreich GmbH, und der Fit Sport Austria GmbH. Letztere wird von den drei Breitensportverbänden ASKÖ, ASVÖ und SPORTUNION getragen. Als Partner ist der Verband alpiner Vereine Österreichs (VAVÖ) an Bord, unterstützt wird das Projekt vom Gesundheits- und vom Sportressort.

Die Initiative ist in die Europäische Woche des Sports unter dem Motto #BeActive eingebettet und unterstützt zudem die ORF-Aktion „Wir bewegen Österreich“.

## Wie es nach der Aktion weitergeht

Auch nach dem Ende der 50 Tage bieten viele Sportvereine und Gemeinden laufend Kurse und offene Bewegungsgruppen an, häufig kostengünstig oder gratis. Wer über die Aktion eingestiegen ist, kann sich bei den örtlichen Vereinen der Breitensportverbände nach regelmäßigen Terminen erkundigen. Entscheidend ist laut den Empfehlungen weniger die Sportart als die Regelmäßigkeit: Jede zusätzliche Bewegungseinheit zählt.','gesundheit','Medizin',NULL,'news','Presseinfo Redaktion','/assets/img/artikel/bewegung-oesterreich-50-tage-bewegung-2026-bilanz-fgoe.webp','Fonds Gesundes Österreich (APA-OTS)','https://www.ots.at/presseaussendung/OTS_20261027_OTS0023/50-tage-bewegung-2026-oesterreich-setzte-ein-starkes-zeichen-fuer-mehr-bewegung-und-gesundheit','published','2026-10-27T20:50:00.000Z','2026-10-27T20:44:17.793Z','Bewegung in Österreich: 50 Tage Bewegung 2026 – Bilanz','Bewegung in Österreich: Bei „50 Tage Bewegung“ gab es 1.700 Gratis-Angebote. Nur 23,6 % erfüllen die Empfehlungen – so viel Bewegung ist sinnvoll.','Bewegung in Österreich','["Bewegung in Österreich","50 Tage Bewegung","50 Tage Bewegung 2026","Bewegungsempfehlungen Österreich","150 Minuten Bewegung pro Woche","Fonds Gesundes Österreich","kostenlose Bewegungsangebote","Bewegung Kinder 60 Minuten","WHO Bewegungsempfehlung"]','Bewegung in Österreich: Gruppe beim gemeinsamen Gehen im herbstlichen Park','Group of adults of mixed ages doing an outdoor walking and gentle exercise session on a gravel path in an Austrian park in autumn, golden leaves, Vienna-style park benches, seen from behind and at a distance, soft evening light, no text, no logos, no readable signs','[{"q":"Wie viel Bewegung wird in Österreich empfohlen?","a":"Erwachsene sollten sich mindestens 150 Minuten pro Woche mit mittlerer Intensität bewegen und zusätzlich die Muskulatur kräftigen. Kinder und Jugendliche von 6 bis 18 Jahren mindestens 60 Minuten täglich."},{"q":"Wie viele Menschen erfüllen die Bewegungsempfehlungen?","a":"Laut Statistik Austria erreichen nur 23,6 Prozent der 18- bis 64-Jährigen sowohl die Ausdauer- als auch die Kraftziele. Weniger als die Hälfte schafft 150 Minuten pro Woche."},{"q":"Was war „50 Tage Bewegung“ 2026?","a":"Eine Initiative von FGÖ und Fit Sport Austria vom 7. September bis 26. Oktober 2026 mit über 1.700 kostenlosen Bewegungsangeboten in ganz Österreich."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
